package com.ngstudio.maze.data

import android.content.Context
import com.ngstudio.maze.core.Level
import com.ngstudio.maze.core.LevelCodec

/**
 * Reads the verified level packs from assets (levels/levels.bin = 5000, levels/daily.bin = 366).
 * The packs are generated by `./gradlew :levelgen:run`; never edit them by hand.
 */
class LevelRepository(private val context: Context) {
    @Volatile private var main: LevelCodec.Pack? = null
    @Volatile private var daily: LevelCodec.Pack? = null

    val isLoaded get() = main != null && daily != null

    /** Blocking; call off the main thread (Splash does). */
    fun load() {
        if (main == null) main = LevelCodec.Pack(context.assets.open("levels/levels.bin").use { it.readBytes() })
        if (daily == null) daily = LevelCodec.Pack(context.assets.open("levels/daily.bin").use { it.readBytes() })
    }

    val count: Int get() = main?.count ?: TOTAL

    /** 1-based level number. */
    fun level(number: Int): Level {
        if (main == null) load()
        return main!!.level((number - 1).coerceIn(0, count - 1))
    }

    fun dailyLevel(dayIndex: Long): Level {
        if (daily == null) load()
        val p = daily!!
        return p.level(Math.floorMod(dayIndex, p.count.toLong()).toInt())
    }

    companion object {
        const val TOTAL = 5000
    }
}
